import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { CSSProperties, useMemo, useState } from 'react';
import {
  IProfit,
  IProfitReport,
} from '../../../core/Interface/profitDetailReport.interface';
import usePageQuery from '../../../core/hooks/usePageQuery';
import { useProfitReportQuery, useGetUserQuery } from '../../posApi';
import useProfitReportColumns from './useProfitReportColumns';
import { IUserInfo } from '../../../core/Interface/user.interface';

const useProfitReport = () => {
  const { page } = usePageQuery();
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data: profitReportData,
    isLoading,
    isFetching,
    error,
  } = useProfitReportQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText: '',
  });

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const ProfitMemo = useMemo(() => {
    return profitReportData?.data as IProfitReport;
  }, [profitReportData?.data]);

  const filteredData = useMemo(() => {
    const text = searchText.toLowerCase().trim();
    return (
      profitReportData &&
      ProfitMemo.data &&
      ProfitMemo.data.filter((record: IProfit) => {
        const code = record.product?.code.toLowerCase();
        const name = record.product?.name.toLowerCase();
        return name?.includes(text) || code?.includes(text);
      })
    );
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ProfitMemo, searchText]);

  const columns = useProfitReportColumns(
    pagination.pageIndex,
    pagination.pageSize,
    currencyCode
  );

  const table = useReactTable({
    data: error ? [] : filteredData ?? [],
    meta: {
      getRowStyles: (row: Row<IProfit>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: ProfitMemo?.totalRecords ?? 0,
    //pageCount: Math.ceil(totalRecords / pageSize),
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: ProfitMemo?.totalRecords ?? 0,
    searchText,
    setSearchText,
  };
};

export default useProfitReport;
